// def __init__(self, v: T) -> None:
//     self.n = 0
//     # An open T may be a reference type, which this store copies.
//     self.v = v  # tpyc: warning(/may copy T into field/)
template<typename T>
inline Dial<T>::Dial(::tpy::readonly_form_t<T> v)
    : n(0),
      v(v) {}

// def gauge(self) -> T:
//     return self.v
template<typename T>
inline ::tpy::val_or_ref_t<T> Dial<T>::gauge() {
    return this->v;
}

// def __init__(self, x: T) -> None:
//     self.x = x
//     self.reads = 0
template<::tpy::ValueType T>
inline Cell<T>::Cell(::tpy::readonly_form_t<T> x)
    : x(x),
      reads(0) {}

// def peek(self) -> Own[T]:  # tpyc: ok
//     self.reads += 1
//     return self.x
template<::tpy::ValueType T>
inline ::tpy::own_return_t<T> Cell<T>::peek() {
    this->reads = ::tpy::add_check<int32_t>(this->reads, 1);
    return this->x;
}

// def bound_own_label[T: OwnLabel](p: T) -> str:
//     s = p.name()  # tpyc: ok
//     return s + "?"
template<OwnLabel T>
std::string bound_own_label(::tpy::param_val_or_ref_t<T> p) {
    std::string s = p.name();
    return (::tpy::str_concat(s, "?"));
}
// def via_bridges[T: Bridges](b: T) -> int32:
//     return b.turn(4) + b.trim()
template<Bridges T>
int32_t via_bridges(::tpy::param_val_or_ref_t<T> b) {
    return (::tpy::add_check<int32_t>(b.turn(4), b.trim()));
}
// def via_swap_bound[T: SwapMixer](m: T) -> int32:
//     return m.mix(hi=3, lo=1)
template<__SwapMixer_Concept__ T>
int32_t via_swap_bound(::tpy::param_val_or_ref_t<T> m) {
    return m.mix(1, 3);
}

